basic.code:
case "$1" in
  start|run) echo "starting" ;;
  stop) echo "stopping" ;;
  *) echo "usage: ..." ;;
esac

intermediate.code:
run_backup() {
  tar -czf "$1" "$2"
}
# tests can stub tar in PATH before calling run_backup

copy_file() {
  local src="$1" dst="$2"
  cp -- "$src" "$dst"
}
copy_file a.txt backup/

count_items() {
  local count=0
  # use count here
  printf '%s\n' "$count"
}

while getopts ':vo:' opt; do
  case "$opt" in
    v) verbose=1 ;;
    o) outfile=$OPTARG ;;
  esac
done
